// Des: Run any catalog job: turn a job row into flow steps and send it through the safety ladder
// Flo: check needed args > resolve host + page path > map label keys to names (packs, owner overrides) > fill secrets > once-only key (once jobs only) > execWrite
// I/O: Job row + Args (caller) > count of items done; errors BadUsage NoElement CapHit NeedApprove NoSecret ...
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const flow = @import("ru-flow-runz.zig"); const jobs = @import("ru-jobs-tabl.zig"); const pack = @import("ut-loca-pack.zig"); const fld = @import("ut-text-fold.zig");
const CF = .{ .snip = 30 };
pub fn argOf(ctx: *task.Ctx, args: task.Args, arg: jobs.Arg) []const u8 { return switch (arg) { .none => "", .text => args.text, .to => args.to, .url => args.url, .title => args.title, .price => args.price, .desc => args.desc, .group => args.group, .photo => args.photo, .opt => args.opt, .date => args.date, .time => args.time, .user => ctx.secr_user, .pass => ctx.secr_pass }; }
pub fn hostBase(ctx: *task.Ctx, host: jobs.Host) []const u8 { return switch (host) { .app => ctx.conf.base_appz_main, .www => ctx.conf.base_urlz_main, .docs => ctx.conf.base_docz_main }; }
pub fn pathOf(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args) ![]const u8 { if (job.path.len == 0) { if (std.mem.startsWith(u8, args.url, "http")) return args.url; return std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ hostBase(ctx, job.host), args.url }); } return std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ hostBase(ctx, job.host), pack.pathOf(ctx.conf, job.path) }); }
fn labsFor(ctx: *task.Ctx, args: task.Args, tpl: jobs.T) ![]const []const u8 { if (tpl.larg != .none) { const val = argOf(ctx, args, tpl.larg); if (val.len > 0) { const one = try ctx.aren.alloc([]const u8, 1); one[0] = val; return one; } } if (tpl.key.len > 0) return pack.lab(ctx.conf, tpl.key); if (tpl.op == .expect and tpl.arg != .none) { const one = try ctx.aren.alloc([]const u8, 1); one[0] = cutUtf8(argOf(ctx, args, tpl.arg), CF.snip); return one; } return &.{}; }
pub fn cutUtf8(text: []const u8, maxn: usize) []const u8 { if (text.len <= maxn) return text; var end = maxn; while (end > 0 and (text[end] & 0xC0) == 0x80) end -= 1; return text[0..end]; }
fn secret(arg: jobs.Arg) bool { return arg == .user or arg == .pass; }
pub fn build(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args, path: []const u8) ![]flow.Step { var out: std.ArrayList(flow.Step) = .empty; for (job.steps) |tpl| { const val = argOf(ctx, args, tpl.arg); if (secret(tpl.arg) and val.len == 0) { if (ctx.mode == .live or ctx.mode == .force) return error.NoSecret; continue; } const optional = (tpl.op == .typez or tpl.op == .upload or tpl.op == .select or tpl.op == .clear) and tpl.arg != .none; if (optional and val.len == 0) continue; if (tpl.op == .expect and tpl.arg != .none and val.len == 0) continue; const txt = switch (tpl.op) { .goto => path, .key, .toggle => tpl.lit, .typez, .upload, .select => val, else => "" }; try out.append(ctx.aren, .{ .op = tpl.op, .role = tpl.role, .labs = try labsFor(ctx, args, tpl), .text = txt, .commit = tpl.commit }); } return out.items; }
fn argHash(ctx: *task.Ctx, args: task.Args, path: []const u8) ![]u8 { const all = try std.fmt.allocPrint(ctx.aren, "{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}", .{ path, args.text, args.to, args.title, args.price, args.desc, args.group, args.photo, args.opt, args.date, args.time, args.url }); return task.hashHex(ctx, all); }
fn needOk(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args) bool { for (job.need) |nd| { if (argOf(ctx, args, nd).len == 0) return false; } return true; }
pub fn runOne(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args) !task.Out { if (!needOk(ctx, job, args)) return error.BadUsage; const path = try pathOf(ctx, job, args); const hsh = try argHash(ctx, args, path); const key = if (job.once) try std.fmt.allocPrint(ctx.aren, "job|{s}|{s}", .{ job.name, hsh }) else try std.fmt.allocPrint(ctx.aren, "run|{s}|{d}", .{ job.name, task.nowMs(ctx) }); const what = try std.fmt.allocPrint(ctx.aren, "{s} at {s}", .{ job.name, path }); const stps = try build(ctx, job, args, path); const prev = ctx.auth; ctx.auth = job.auth; defer ctx.auth = prev; return task.execWrite(ctx, job.kind, key, what, job.risk == .x, stps); }
pub fn run(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args) !u32 { const out = try runOne(ctx, job, args); return if (out == .dupe) 0 else 1; }
